questionvariables.text:
/* Randomize the sector angle: realistic wiper sweep, 60° to 180°, steps of 10° */
theta: rand_with_step(60, 180, 10);

/* Randomize the wiper length (difference between outer and inner radius) */
Wiper: rand_with_step(7, 47, 7);

/* Randomize the outer radius, then derive inner radius from Wiper */
R: rand_with_step(7, 140, 7) + Wiper;
r: R - Wiper;

/* pi = 22/7 as specified */
Pi_val: 22/7;

/* Intermediate working values */
R_sq: R^2;
r_sq: r^2;
Radius_difference: R_sq - r_sq;

/* Area of the annular sector (shaded region) */
A: (theta/360) * Pi_val * Radius_difference;
A_val: float(A);

/* Round to 3 decimal places for the final displayed/marked answer */
A_3dp: float(decimalplaces(A, 3));
